@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@500;600;700;800&family=Inter:wght@400;500;600&display=swap');

:root {
  --bg: #f5f2ed;
  --text: #1a1a1a;
  --muted: #57524b;
  --line: #d7cec1;
  --accent: #a06f54;
  --terracotta: #bf7d5d;
  --sage: #97a18e;
  --sand: #c8b59e;
  --max-width: 1240px;
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  font-family: 'Inter', sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
}

a { color: inherit; text-decoration: none; }

.site-shell {
  min-height: 100vh;
  padding: 2rem clamp(1.25rem, 2.3vw, 2.5rem) 3rem;
}

.topbar {
  max-width: var(--max-width);
  margin: 0 auto 3.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}

.brand {
  font-family: 'Playfair Display', serif;
  font-size: clamp(1.45rem, 2vw, 2.1rem);
  letter-spacing: 0.01em;
}

.nav {
  display: flex;
  gap: 2rem;
  font-size: 0.95rem;
}

.nav a { position: relative; }
.nav a::after {
  content: '';
  position: absolute;
  left: 0;
  bottom: -0.25rem;
  width: 100%;
  height: 1px;
  background: currentColor;
  transform: scaleX(0);
  transform-origin: left;
  transition: transform .25s ease;
}
.nav a:hover::after,
.nav a[aria-current="page"]::after { transform: scaleX(1); }

.menu-button {
  display: none;
  border: 0;
  background: transparent;
  font: inherit;
  color: var(--text);
  padding: 0.25rem;
  cursor: pointer;
}

.menu-icon {
  width: 1.6rem;
  display: grid;
  gap: .28rem;
}
.menu-icon span {
  display: block;
  height: 1px;
  background: var(--text);
}

.mobile-overlay {
  position: fixed;
  inset: 0;
  background: rgba(245, 242, 237, 0.98);
  padding: 2rem 1.5rem;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  transform: translateY(-100%);
  transition: transform .35s ease;
  z-index: 50;
}
.mobile-overlay.open { transform: translateY(0); }
.mobile-overlay nav {
  display: grid;
  gap: 1.1rem;
  font-family: 'Playfair Display', serif;
  font-size: clamp(2rem, 7vw, 3.8rem);
}
.mobile-close {
  align-self: flex-end;
  border: 0;
  background: transparent;
  font-size: 1rem;
  cursor: pointer;
}

.container {
  max-width: var(--max-width);
  margin: 0 auto;
}

.hero-title {
  font-family: 'Playfair Display', serif;
  font-size: clamp(2.7rem, 8vw, 7.3rem);
  line-height: .95;
  margin: 0;
  max-width: 11ch;
}

.eyebrow {
  text-transform: uppercase;
  letter-spacing: .12em;
  font-size: .72rem;
  color: var(--muted);
}

.lead {
  max-width: 55ch;
  font-size: clamp(1.05rem, 1.5vw, 1.25rem);
  color: #2e2b27;
}

.section {
  margin-top: clamp(4rem, 10vw, 8.5rem);
}

.media-grid {
  margin-top: 2.5rem;
  display: grid;
  grid-template-columns: 1.2fr 1fr 1fr;
  grid-template-rows: 260px 200px;
  gap: 1rem;
}
.block { border-radius: 2px; }
.block-1 { grid-row: 1 / 3; background: linear-gradient(130deg, #c78c71, #b87256); }
.block-2 { background: linear-gradient(130deg, #9cab93, #859078); }
.block-3 { background: linear-gradient(130deg, #cfbca3, #b39f86); }
.block-4 { grid-column: 2 / 4; background: linear-gradient(110deg, #8a6b59, #ad8168); }

.marquee-area {
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  padding: 1.4rem 0;
  overflow: hidden;
}
.marquee-track {
  display: flex;
  width: max-content;
  white-space: nowrap;
  will-change: transform;
  font-family: 'Playfair Display', serif;
  font-size: clamp(1.2rem, 2.8vw, 2.35rem);
  margin: .35rem 0;
}
.marquee-track span {
  display: inline-flex;
  align-items: center;
  margin-right: 2.5rem;
}
.marquee-track span::after {
  content: '•';
  margin-left: 2.5rem;
  color: var(--accent);
}

.service-list {
  display: grid;
  gap: 2rem;
}
.service-item h3 {
  margin: 0 0 .6rem;
  font-family: 'Playfair Display', serif;
  font-size: clamp(1.45rem, 2.5vw, 2.1rem);
}
.service-item p { margin: 0; max-width: 72ch; color: #2b2823; }

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 2.1rem 2rem;
}
.client-card h3 {
  margin: 0 0 .45rem;
  font-family: 'Playfair Display', serif;
  font-size: 1.45rem;
}
.client-card p { margin: 0; color: #2f2b25; }

.letter {
  max-width: 72ch;
  margin: 0 auto;
  font-size: 1.08rem;
}
.letter h1 {
  font-family: 'Playfair Display', serif;
  font-size: clamp(2.4rem, 7vw, 5.8rem);
  line-height: .95;
  margin: 0 0 2rem;
}
.letter p { margin: 0 0 1.25rem; }

.contact-hero {
  min-height: calc(100vh - 12rem);
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 2.5rem;
}
.contact-hero h1 {
  margin: 0;
  font-family: 'Playfair Display', serif;
  font-size: clamp(4rem, 20vw, 16rem);
  line-height: .78;
}
.contact-links {
  display: flex;
  flex-wrap: wrap;
  gap: 1.25rem 2rem;
  font-size: 1.15rem;
}

@media (max-width: 980px) {
  .nav { display: none; }
  .menu-button { display: block; }
  .media-grid { grid-template-columns: 1fr; grid-template-rows: repeat(4, 180px); }
  .block-1, .block-2, .block-3, .block-4 { grid-column: auto; grid-row: auto; }
  .clients-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 680px) {
  .clients-grid { grid-template-columns: 1fr; }
}
